#!/usr/bin/env node
/**
 * Generate `public/analytics.js` — the PostHog bootstrap every page loads —
 * from PUBLIC_POSTHOG_PROJECT_TOKEN and PUBLIC_POSTHOG_HOST, the same
 * variables the blog (nwber.github.io) uses. The token never lives in git:
 * CI passes repo Actions variables, local runs read `.env`.
 *
 *   node scripts/generate-analytics.mjs            # warn and skip when unset
 *   node scripts/generate-analytics.mjs --require  # fail when unset (CI)
 *
 * `npm run dev` regenerates automatically (predev); `npm run analytics` runs
 * it on demand. The generated file is gitignored; without it the pages'
 * /analytics.js request 404s and analytics stays off (in local dev only).
 *
 * The snippet and init options are kept in sync with the blog's
 * src/components/PostHog.astro — change them together.
 */

import { existsSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";

const OUT_FILE = fileURLToPath(new URL("../public/analytics.js", import.meta.url));
const ENV_FILE = fileURLToPath(new URL("../.env", import.meta.url));

/** Public variables the generator needs; names match the blog's. */
export const ANALYTICS_ENV_VARS = ["PUBLIC_POSTHOG_PROJECT_TOKEN", "PUBLIC_POSTHOG_HOST"];

/** JSON string literal safe to embed in a script (no `</script>` breakout). */
const literal = (value) => JSON.stringify(value).replaceAll("<", "\\u003c");

/**
 * The PostHog bootstrap, exactly as the blog runs it: the official snippet,
 * then init with history-change pageviews, exception capture (unhandled
 * errors and rejections, not console errors), and trace headers for this
 * hostname. Throws when either input is missing.
 */
export function buildAnalyticsScript({ token, host }) {
  if (!token) throw new Error("PUBLIC_POSTHOG_PROJECT_TOKEN is required");
  if (!host) throw new Error("PUBLIC_POSTHOG_HOST is required");
  return `// Generated by scripts/generate-analytics.mjs — do not edit.
if (!window.__posthog_initialized) {
  window.__posthog_initialized = true;
  !function(t,e){var o,n,p,r;e.__SV||(window.posthog=e,e._i=[],e.init=function(i,s,a){function g(t,e){var o=e.split(".");2==o.length&&(t=t[o[0]],e=o[1]),t[e]=function(){t.push([e].concat(Array.prototype.slice.call(arguments,0)))}}(p=t.createElement("script")).type="text/javascript",p.crossOrigin="anonymous",p.async=!0,p.src=s.api_host.replace(".i.posthog.com","-assets.i.posthog.com")+"/static/array.js",(r=t.getElementsByTagName("script")[0]).parentNode.insertBefore(p,r);var u=e;for(void 0!==a?u=e[a]=[]:a="posthog",u.people=u.people||[],u.toString=function(t){var e="posthog";return"posthog"!==a&&(e+="."+a),t||(e+=" (stub)"),e},u.people.toString=function(){return u.toString(1)+".people (stub)"},o="init capture identify alias people.set people.set_once reset set_config register register_once unregister opt_out_capturing has_opted_out_capturing opt_in_capturing has_opted_in_capturing isFeatureEnabled onFeatureFlags getFeatureFlag getFeatureFlagResult reloadFeatureFlags group updateEarlyAccessFeatureEnrollment getEarlyAccessFeatures getActiveMatchingSurveys getSurveys getNextSurveyStep onSessionId get_distinct_id captureException startSessionRecording stopSessionRecording renderSurvey on".split(" "),n=0;n<o.length;n++)g(u,o[n]);e._i.push([i,s,a])},e.__SV=1)}(document,window.posthog||[]);
  posthog.init(${literal(token)}, {
    api_host: ${literal(host)},
    capture_pageview: 'history_change',
    capture_exceptions: {
      capture_unhandled_errors: true,
      capture_unhandled_rejections: true,
      capture_console_errors: false
    },
    tracing_headers: [window.location.hostname]
  });
}
`;
}

function main() {
  const required = process.argv.includes("--require");
  try {
    process.loadEnvFile(ENV_FILE);
  } catch {
    // No .env — CI supplies the variables instead.
  }

  const missing = ANALYTICS_ENV_VARS.filter((name) => !process.env[name]);
  if (missing.length > 0) {
    if (required) {
      console.error(
        `error: ${missing.join(", ")} not set — add the repo Actions variables before deploying`,
      );
      process.exitCode = 1;
    } else if (existsSync(OUT_FILE)) {
      console.warn(
        `warning: ${missing.join(", ")} not set — keeping the existing public/analytics.js`,
      );
    } else {
      console.warn(
        `warning: ${missing.join(", ")} not set — public/analytics.js not generated, analytics stays off`,
      );
    }
    return;
  }

  writeFileSync(
    OUT_FILE,
    buildAnalyticsScript({
      token: process.env.PUBLIC_POSTHOG_PROJECT_TOKEN,
      host: process.env.PUBLIC_POSTHOG_HOST,
    }),
  );
  console.log("wrote public/analytics.js");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
